import { defineSlot } from '../Slot';
import type { Person } from '../../features/people/people';

/** Header cells of the people table: one `<th>` per column a feature adds to every person's row. */
export const PeopleHead = defineSlot<{ sheetId: string; user: string }>('people.head');

/** Cells of a person's row in the people table: each contribution renders its own `<td>`s, in
 *  the same order as its PeopleHead cells. */
export const PersonRow = defineSlot<{ sheetId: string; user: string; person: Person }>('person.row');
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { type Person } from '../people/people';
import { usePersonRowAction } from '../people/rowAction';
import { useWatches, watchesKey, type Watch } from './watch';

function WatchHead() {
  return (
    <>
      <th>Watched</th>
      <th />
    </>
  );
}

/** Whether the signed-in user watches the person, and the button that starts or stops them watching. A settle,
 *  approve or re-settle of a watched person's claim notifies each watcher (in the audit file). A refused change shows
 *  the row's error. */
function PersonWatch({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const watches = useWatches(sheetId);
  const submit = useSubmitOnce();
  const rowAction = usePersonRowAction(sheetId, person.id, 'watch');
  const watched = (watches.data ?? []).some((w) => w.personId === person.id && w.user === user);
  const watch = useMutation({
    mutationFn: (on: boolean) =>
      postJson<Watch>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/watch`, { on, by: user }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: watchesKey(sheetId) }),
    onSettled: submit.end,
  });

  return (
    <>
      <td data-testid="person-watched">{watched ? 'yes' : 'no'}</td>
      <td>
        <button
          type="button"
          data-testid="person-watch"
          disabled={watch.isPending || !watches.isSuccess}
          onClick={() => {
            if (!submit.begin()) return;
            rowAction.take();
            watch.reset();
            watch.mutate(!watched);
          }}
        >
          {watched ? 'Unwatch' : 'Watch'}
        </button>
        {watch.isError && rowAction.isLatest && <span data-testid="person-error"> Could not change watching this person.</span>}
      </td>
    </>
  );
}

export const contributions = [
  PeopleHead.fill({ order: 70, Component: WatchHead }),
  PersonRow.fill({ order: 70, Component: PersonWatch }),
];
import { useCallback, useSyncExternalStore } from 'react';

// The action last taken on each person's row (by sheet and person id). A row shows one error at a time: an action's
// error shows only while it is the latest action taken on that row, so taking the next action clears the last error.
const latest = new Map<string, string>();
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** Marks `action` as the latest taken on the person's row (call when it is taken), and whether it still is. */
export function usePersonRowAction(sheetId: string, personId: number, action: string) {
  const key = `${sheetId}\u0000${personId}`;
  const current = useSyncExternalStore(subscribe, () => latest.get(key));
  const take = useCallback(() => {
    latest.set(key, action);
    listeners.forEach((l) => l());
  }, [key, action]);
  return { take, isLatest: current === undefined || current === action };
}
